// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RevenueAction) predicate.RevenueAction {
	return predicate.RevenueAction(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RevenueAction) predicate.RevenueAction {
	return predicate.RevenueAction(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RevenueAction) predicate.RevenueAction {
	return predicate.RevenueAction(sql.NotPredicates(p))
}
